"use client";

// Configuration panel — the compact backtest-settings surface. Every control is
// bound to the DSL's legal values; the readback is generated by backend template
// code from the validated spec. Nothing runs until "Run backtest".

import { useEffect, useRef, useState } from "react";
import { api } from "@/lib/api";
import type { ValidateResult } from "@/lib/types";
import { Notice, Panel } from "@/components/ui/Primitives";
import { IconRun, IconSettings, IconWarning } from "@/components/ui/Icons";

type Spec = Record<string, any>;

const REBALANCE = ["daily", "weekly", "monthly", "quarterly", "annual"];
const WEIGHTING = ["equal", "rank", "inverse_vol"];
const BENCHMARK = ["SPY", "QQQ", "sixty_forty"];
const DIRECTION = ["top", "bottom"];
const UNIVERSE_LABEL: Record<string, string> = {
  sp500: "S&P 500 · current members",
  nasdaq100: "Nasdaq-100 · current members",
  dow30: "Dow 30 · current members",
  sector_etfs: "11 sector ETFs",
  user_watchlist: "Custom watchlist",
};
const SIGNAL_LABEL: Record<string, string> = {
  return: "Total return",
  daily_return: "1-day return",
  volatility: "Volatility",
  rsi: "RSI",
  drawdown_from_high: "Drawdown from high",
  sma_cross: "Moving-average cross",
};

export default function SpecReview({
  initialSpec, assumptions, onRun,
}: {
  initialSpec: Spec;
  assumptions: string[];
  onRun: (spec: Spec) => void;
}) {
  const [spec, setSpec] = useState<Spec>(initialSpec);
  const [validation, setValidation] = useState<ValidateResult | null>(null);
  const [showJson, setShowJson] = useState(false);
  const debounce = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => { setSpec(initialSpec); }, [initialSpec]);

  useEffect(() => {
    api("/api/event", { method: "POST", json: { type: "ui_spec_card_shown" } })
      .catch(() => undefined);
  }, []);

  useEffect(() => {
    if (debounce.current) clearTimeout(debounce.current);
    debounce.current = setTimeout(() => {
      api<ValidateResult>("/api/validate-spec", { method: "POST", json: { spec } })
        .then(setValidation)
        .catch(() => setValidation(null));
    }, 300);
    return () => { if (debounce.current) clearTimeout(debounce.current); };
  }, [spec]);

  const set = (path: string[], value: unknown) => {
    setSpec((prev) => {
      const next = structuredClone(prev);
      let node: any = next;
      for (const key of path.slice(0, -1)) {
        node[key] = node[key] ?? {};
        node = node[key];
      }
      node[path[path.length - 1]] = value;
      return next;
    });
  };

  const sel = spec.selection ?? {};
  const isStatic = Array.isArray(sel.static_allocation);
  const rankBy = sel.rank_by ?? {};
  const valid = validation?.valid ?? false;

  return (
    <Panel
      title="Configuration"
      icon={<IconSettings size={15} />}
      right={
        <button className="ghost" onClick={() => setShowJson(!showJson)}>
          {showJson ? "Hide" : "Raw"} JSON
        </button>
      }
    >
      <div className="specrow">
        <span className="k">Name</span>
        <span className="v">
          <input type="text" value={spec.name ?? ""} maxLength={80} style={{ flex: 1, minWidth: 0 }}
            onChange={(e) => set(["name"], e.target.value)} aria-label="Strategy name" />
        </span>
      </div>

      <div className="specrow">
        <span className="k">Universe</span>
        <span className="v">
          {UNIVERSE_LABEL[spec.universe?.preset] ?? spec.universe?.preset}
          {validation?.universe_size ? (
            <span className="faint">{validation.universe_size} tickers</span>
          ) : null}
        </span>
      </div>

      {isStatic ? (
        <div className="specrow">
          <span className="k">Allocation</span>
          <span className="v">
            {sel.static_allocation
              .map((p: any) => `${Math.round(p.weight * 100)}% ${p.ticker}`)
              .join(" · ")}
          </span>
        </div>
      ) : (
        <>
          <div className="specrow">
            <span className="k">Signal</span>
            <span className="v">
              {SIGNAL_LABEL[rankBy.type] ?? rankBy.type ?? "—"}
              {rankBy.lookback_days != null && (
                <>
                  <input type="number" min={1} max={756} value={rankBy.lookback_days}
                    aria-label="Lookback in trading days" style={{ width: 68 }}
                    onChange={(e) =>
                      set(["selection", "rank_by", "lookback_days"], Number(e.target.value))} />
                  <span className="faint">trading days</span>
                </>
              )}
              {rankBy.skip_days > 0 && <span className="faint">skip {rankBy.skip_days}d</span>}
            </span>
          </div>
          <div className="specrow">
            <span className="k">Selection</span>
            <span className="v">
              <select value={sel.direction ?? "top"} aria-label="Rank direction"
                onChange={(e) => set(["selection", "direction"], e.target.value)}>
                {DIRECTION.map((d) => <option key={d} value={d}>{d}</option>)}
              </select>
              <input type="number" min={1} max={50} value={sel.n ?? 5} style={{ width: 60 }}
                aria-label="Number of holdings"
                onChange={(e) => set(["selection", "n"], Number(e.target.value))} />
              <span className="faint">holdings</span>
            </span>
          </div>
          <div className="specrow">
            <span className="k">Weighting</span>
            <span className="v">
              <select value={spec.weighting ?? "equal"} aria-label="Weighting"
                onChange={(e) => set(["weighting"], e.target.value)}>
                {WEIGHTING.map((w) => <option key={w} value={w}>{w.replace("_", " ")}</option>)}
              </select>
            </span>
          </div>
        </>
      )}

      <div className="specrow">
        <span className="k">Rebalance</span>
        <span className="v">
          <select value={spec.rebalance ?? "monthly"} aria-label="Rebalance frequency"
            onChange={(e) => set(["rebalance"], e.target.value)}>
            {REBALANCE.map((r) => <option key={r} value={r}>{r}</option>)}
          </select>
          {spec.entry_exit?.hold_days != null && (
            <>
              <span className="faint">hold</span>
              <input type="number" min={1} max={252} value={spec.entry_exit.hold_days}
                aria-label="Hold days" style={{ width: 60 }}
                onChange={(e) => set(["entry_exit", "hold_days"], Number(e.target.value))} />
              <span className="faint">days</span>
            </>
          )}
        </span>
      </div>

      <div className="specrow">
        <span className="k">Date range</span>
        <span className="v">
          <input type="date" value={spec.window?.start ?? ""} aria-label="Window start"
            onChange={(e) => set(["window", "start"], e.target.value)} />
          <span className="faint">→</span>
          <input type="date" value={spec.window?.end ?? ""} aria-label="Window end"
            onChange={(e) => set(["window", "end"], e.target.value)} />
        </span>
      </div>

      <div className="specrow">
        <span className="k">Benchmark</span>
        <span className="v">
          <select value={spec.benchmark ?? "SPY"} aria-label="Benchmark"
            onChange={(e) => set(["benchmark"], e.target.value)}>
            {BENCHMARK.map((b) => (
              <option key={b} value={b}>{b === "sixty_forty" ? "60/40 SPY+AGG" : b}</option>
            ))}
          </select>
          <span className="faint">always compared</span>
        </span>
      </div>

      <div className="specrow">
        <span className="k">Costs</span>
        <span className="v">
          0 / 5 / 20 bps sweep
          <span className="faint">fixed — scaled by measured turnover</span>
        </span>
      </div>

      {validation?.readback && (
        <p className="faint" style={{ marginTop: 14, lineHeight: 1.55, fontStyle: "italic" }}>
          {validation.readback}
        </p>
      )}

      {assumptions.map((a) => (
        <Notice key={a} kind="warn">Assumed — {a}</Notice>
      ))}
      {validation?.warnings?.map((w) => (
        <Notice key={w} kind="warn">{w}</Notice>
      ))}
      {validation && !validation.valid &&
        validation.errors.map((e) => <Notice key={e} kind="err">{e}</Notice>)}

      {showJson && (
        <pre className="scroll-x mono" style={{
          background: "var(--surface-2)", border: "1px solid var(--line)",
          borderRadius: "var(--r-sm)", padding: 12, fontSize: 11.5, marginTop: 12,
        }}>
          {JSON.stringify(validation?.expanded_spec ?? spec, null, 2)}
        </pre>
      )}

      <div className="row" style={{ marginTop: 16 }}>
        <button className="primary" disabled={!valid}
          onClick={() => onRun(validation?.expanded_spec ?? spec)}>
          <IconRun size={13} /> Run backtest
        </button>
        <span className="faint">
          {valid ? "Runs the full audit — no toggle." : "Resolve the notices above."}
        </span>
      </div>
    </Panel>
  );
}
